// --- amsspy.FDb.ind_session.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool amsspy::ind_session_InsertMaybe(amsspy::FSession& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_session_next == (amsspy::FSession*)-1)) {// check if in hash already
        row.ind_session_hashval = algo::cstring_Hash(0, row.session);
        ind_session_Reserve(1);
        u32 index = row.ind_session_hashval & (_db.ind_session_buckets_n - 1);
        amsspy::FSession* *prev = &_db.ind_session_buckets_elems[index];
        do {
            amsspy::FSession* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).session == row.session) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_session_next;
        } while (true);
        if (retval) {
            row.ind_session_next = *prev;
            _db.ind_session_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- amsspy.FDb.ind_session.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void amsspy::ind_session_Remove(amsspy::FSession& row) {
    if (LIKELY(row.ind_session_next != (amsspy::FSession*)-1)) {// check if in hash already
        u32 index = row.ind_session_hashval & (_db.ind_session_buckets_n - 1);
        amsspy::FSession* *prev = &_db.ind_session_buckets_elems[index]; // addr of pointer to current element
        while (amsspy::FSession *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_session_next; // unlink (singly linked list)
                _db.ind_session_n--;
                row.ind_session_next = (amsspy::FSession*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_session_next;
        }
    }
}

// --- amsspy.FDb.ind_session.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void amsspy::ind_session_Reserve(int n) {
    ind_session_AbsReserve(_db.ind_session_n + n);
}

// --- amsspy.FDb.ind_session.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void amsspy::ind_session_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_session_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(amsspy::FSession*);
        u32 new_size = new_nbuckets * sizeof(amsspy::FSession*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        amsspy::FSession* *new_buckets = (amsspy::FSession**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("amsspy.out_of_memory  field:amsspy.FDb.ind_session");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_session_buckets_n; i++) {
            amsspy::FSession* elem = _db.ind_session_buckets_elems[i];
            while (elem) {
                amsspy::FSession &row        = *elem;
                amsspy::FSession* next       = row.ind_session_next;
                u32 index          = row.ind_session_hashval & (new_nbuckets-1);
                row.ind_session_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_session_buckets_elems, old_size);
        _db.ind_session_buckets_elems = new_buckets;
        _db.ind_session_buckets_n = new_nbuckets;
    }
}

