// --- amsspy.FDb.session.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* amsspy::session_AllocMem() {
    u64 new_nelems     = _db.session_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    amsspy::FSession*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.session_lary[bsr];
        if (!lev) {
            lev=(amsspy::FSession*)algo_lib::malloc_AllocMem(sizeof(amsspy::FSession) * (u64(1)<<bsr));
            _db.session_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.session_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- amsspy.FDb.session.RemoveAll
// Remove all elements from Lary
void amsspy::session_RemoveAll() {
    for (u64 n = _db.session_n; n>0; ) {
        n--;
        session_qFind(u64(n)).~FSession(); // destroy last element
        _db.session_n = i64(n);
    }
}

// --- amsspy.FDb.session.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void amsspy::session_RemoveLast() {
    u64 n = _db.session_n;
    if (n > 0) {
        n -= 1;
        session_qFind(u64(n)).~FSession();
        _db.session_n = i64(n);
    }
}

