// --- amsspy.FDb..Init
// Set all fields to initial values.
void amsspy::FDb_Init() {
    // initialize hash table for amsspy::FSession;
    _db.ind_session_n             	= 0; // (amsspy.FDb.ind_session)
    _db.ind_session_buckets_n     	= 4; // (amsspy.FDb.ind_session)
    _db.ind_session_buckets_elems 	= (amsspy::FSession**)algo_lib::malloc_AllocMem(sizeof(amsspy::FSession*)*_db.ind_session_buckets_n); // initial buckets (amsspy.FDb.ind_session)
    if (!_db.ind_session_buckets_elems) {
        FatalErrorExit("out of memory"); // (amsspy.FDb.ind_session)
    }
    memset(_db.ind_session_buckets_elems, 0, sizeof(amsspy::FSession*)*_db.ind_session_buckets_n); // (amsspy.FDb.ind_session)
    // initialize LAry session (amsspy.FDb.session)
    _db.session_n = 0;
    memset(_db.session_lary, 0, sizeof(_db.session_lary)); // zero out all level pointers
    amsspy::FSession* session_first = (amsspy::FSession*)algo_lib::malloc_AllocMem(sizeof(amsspy::FSession) * (u64(1)<<4));
    if (!session_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.session_lary[i]  = session_first;
        session_first    += 1ULL<<i;
    }
    // initialize LAry shm (amsspy.FDb.shm)
    _db.shm_n = 0;
    memset(_db.shm_lary, 0, sizeof(_db.shm_lary)); // zero out all level pointers
    amsspy::FShm* shm_first = (amsspy::FShm*)algo_lib::malloc_AllocMem(sizeof(amsspy::FShm) * (u64(1)<<4));
    if (!shm_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.shm_lary[i]  = shm_first;
        shm_first    += 1ULL<<i;
    }
    // initialize hash table for amsspy::FShm;
    _db.ind_shm_n             	= 0; // (amsspy.FDb.ind_shm)
    _db.ind_shm_buckets_n     	= 4; // (amsspy.FDb.ind_shm)
    _db.ind_shm_buckets_elems 	= (amsspy::FShm**)algo_lib::malloc_AllocMem(sizeof(amsspy::FShm*)*_db.ind_shm_buckets_n); // initial buckets (amsspy.FDb.ind_shm)
    if (!_db.ind_shm_buckets_elems) {
        FatalErrorExit("out of memory"); // (amsspy.FDb.ind_shm)
    }
    memset(_db.ind_shm_buckets_elems, 0, sizeof(amsspy::FShm*)*_db.ind_shm_buckets_n); // (amsspy.FDb.ind_shm)
    _db.cd_shm_poll_head = NULL; // (amsspy.FDb.cd_shm_poll)
    _db.cd_shm_poll_n = 0; // (amsspy.FDb.cd_shm_poll)

    amsspy::InitReflection();
}

