// --- amsspy...StaticCheck
void amsspy::StaticCheck() {
    algo_assert(_offset_of(amsspy::FieldId, value) + sizeof(((amsspy::FieldId*)0)->value) == sizeof(amsspy::FieldId));
}

// --- amsspy...main
int main(int argc, char **argv) {
    try {
        lib_json::FDb_Init();
        algo_lib::FDb_Init();
        lib_ams::FDb_Init();
        amsspy::FDb_Init();
        algo_lib::_db.argc = argc;
        algo_lib::_db.argv = argv;
        algo_lib::IohookInit();
        algo_lib::_db.clock = algo::CurrSchedTime(); // initialize clock
        amsspy::ReadArgv(); // dmmeta.main:amsspy
        amsspy::Main(); // user-defined main
    } catch(algo_lib::ErrorX &x) {
        prerr("amsspy.error  " << x); // there may be additional hints in DetachBadTags
        algo_lib::_db.exit_code = 1;
    }
    if (algo_lib::_db.last_signal) {
        algo_lib::_db.exit_code = 1;
    }
    try {
        amsspy::FDb_Uninit();
        lib_ams::FDb_Uninit();
        algo_lib::FDb_Uninit();
        lib_json::FDb_Uninit();
    } catch(algo_lib::ErrorX &) {
        // don't print anything, might crash
        algo_lib::_db.exit_code = 1;
    }
    // only the lower 1 byte makes it to the outside world
    (void)i32_UpdateMin(algo_lib::_db.exit_code,255);
    return algo_lib::_db.exit_code;
}

